create extension if not exists pgcrypto;
create type if not exists public.app_role as enum ('super_admin','administrator','headteacher','teacher','accountant','librarian','parent','student','staff');
create table if not exists public.schools(id uuid primary key default gen_random_uuid(),name text not null,location text,phone text,email text,logo_url text,academic_year text default '2026',current_term text default 'Term 1',currency text default 'UGX',created_at timestamptz default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,school_id uuid references public.schools(id) on delete set null,full_name text,role public.app_role default 'staff',phone text,active boolean default true,created_at timestamptz default now());
create table if not exists public.classes(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,name text not null,stream text,academic_year text,active boolean default true,created_at timestamptz default now());
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,name text not null,code text,active boolean default true,created_at timestamptz default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,admission_number text not null,first_name text not null,middle_name text,last_name text not null,date_of_birth date,gender text,photo_url text,class_id uuid references public.classes(id) on delete set null,address text,previous_school text,emergency_contact text,active boolean default true,created_at timestamptz default now(),unique(school_id,admission_number));
create table if not exists public.parents(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,full_name text not null,phone text,email text,address text,created_at timestamptz default now());
create table if not exists public.student_parents(student_id uuid references public.students(id) on delete cascade,parent_id uuid references public.parents(id) on delete cascade,relationship text,primary_contact boolean default false,primary key(student_id,parent_id));
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),school_id uuid references public.schools(id) on delete cascade,profile_id uuid references public.profiles(id) on delete set null,staff_number text,full_name text not null,phone text,email text,position text,department text,created_at timestamptz default now());
alter table public.profiles enable row level security;
create policy "users read own profile" on public.profiles for select to authenticated using(id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),'staff') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
